private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (!bb.hasRemaining()) {
        return i;
    }
    try {
        int first = bb.get() & 0xFF;
        if (first < 0x80) {
            sb.append((char) first);
        } else if ((first >> 5) == 0b110) { // 2‑byte sequence
            int b2 = bb.get() & 0x3F;
            int code = ((first & 0x1F) << 6) | b2;
            sb.append((char) code);
        } else if ((first >> 4) == 0b1110) { // 3‑byte sequence
            int b2 = bb.get() & 0x3F;
            int b3 = bb.get() & 0x3F;
            int code = ((first & 0x0F) << 12) | (b2 << 6) | b3;
            sb.append((char) code);
        } else if ((first >> 3) == 0b11110) { // 4‑byte sequence (surrogate pair)
            int b2 = bb.get() & 0x3F;
            int b3 = bb.get() & 0x3F;
            int b4 = bb.get() & 0x3F;
            int code = ((first & 0x07) << 18) | (b2 << 12) | (b3 << 6) | b4;
            code -= 0x10000;
            char high = (char) ((code >> 10) + 0xD800);
            char low = (char) ((code & 0x3FF) + 0xDC00);
            sb.append(high).append(low);
        } else {
            sb.append('?'); // invalid leading byte
        }
    } catch (BufferUnderflowException e) {
        sb.append('?'); // incomplete sequence
    }
    return i + 1;
}

