public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new NullPointerException("Message cannot be null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema cannot be null");
    }
    if (buffer == null) {
        buffer = LinkedBuffer.allocate(LinkedBuffer.DEFAULT_BUFFER_SIZE);
    }

    // Encode the message into the LinkedBuffer using the provided schema
    CodedOutputStream bufferCos = CodedOutputStream.newInstance(buffer);
    try {
        schema.writeTo(message, bufferCos);
        bufferCos.flush();
    } catch (IOException e) {
        throw new IOException("Failed to encode message", e);
    }

    int size = buffer.length();

    // Write the length prefix and the encoded message to the OutputStream
    CodedOutputStream outCos = CodedOutputStream.newInstance(out);
    try {
        outCos.writeRawVarint32(size);
        buffer.writeTo(out);
        outCos.flush();
    } catch (IOException e) {
        throw new IOException("Failed to write delimited message", e);
    }

    return size;
}

