private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){
    if(str == null) {
        return suffix == null;
    }
    if(suffix == null) {
        return false;
    }
    if(suffix.isEmpty()) {
        return true;
    }
    int suffixLength = suffix.length();
    if(str.length() < suffixLength) {
        return false;
    }
    int startIndex = str.length() - suffixLength;
    return str.regionMatches(ignoreCase, startIndex, suffix, 0, suffixLength);
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode){
    List<PathSegmentImpl> result = new ArrayList<>();
    if (u == null) {
        return result;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return result;
    }
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    String[] segs = path.split("/", -1);
    for (String seg : segs) {
        if (seg.isEmpty()) {
            continue;
        }
        String value = seg;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(seg, "UTF-8");
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        result.add(new PathSegmentImpl(value));
    }
    return result;
}

