    }
    int i = len - 1;
    while (i >= 0 && Character.isWhitespace(str.charAt(i))) {
        i--;
    }
    if (i == len - 1) {
        return str;
    }
    if (i < 0) {
        return "";
    }
    return str.substring(0, i + 1);
}

