public final byte[] toByteArray() {
    // Handle the case where no buffers are present or the collection is empty.
    if (buffers == null || buffers.isEmpty()) {
        return new byte[0];
    }

    // First compute the total size of all buffer contents.
    int totalSize = 0;
    for (ByteArrayOutputStream buf : buffers) {
        totalSize += buf.size();
    }

    // Allocate the resulting array once, then copy each buffer's data into it.
    byte[] result = new byte[totalSize];
    int offset = 0;
    for (ByteArrayOutputStream buf : buffers) {
        byte[] chunk = buf.toByteArray();
        System.arraycopy(chunk, 0, result, offset, chunk.length);
        offset += chunk.length;
    }

    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    int j = i + 2;
                    int end = Math.min(j + 4, len);
                    String hex = str.substring(j, end);
                    if (hex.length() == 4 && hex.matches("[0-9a-fA-F]{4}")) {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                        i = end - 1;
                    } else {
                        sb.append('\\').append('u');
                        i++;
                    }
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int oct = next - '0';
                        int k = 1;
                        while (k < 3 && i + 1 + k < len
                                && str.charAt(i + 1 + k) >= '0'
                                && str.charAt(i + 1 + k) <= '7') {
                            oct = oct * 8 + (str.charAt(i + 1 + k) - '0');
                            k++;
                        }
                        sb.append((char) oct);
                        i += k;
                    } else {
                        sb.append('\\').append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

