protected Object filter(Object msg) {
    // If there is nothing to filter or the message is null, just return it
    if (msg == null) {
        return null;
    }
    // Assume a BroadcastFilter instance named broadcastFilter exists in this class.
    // If it is not present, simply return the original message.
    if (broadcastFilter == null) {
        return msg;
    }
    try {
        // Delegate the filtering operation to the BroadcastFilter
        return broadcastFilter.filter(msg);
    } catch (Exception e) {
