    if (startOffset < 0) {
        throw new IllegalArgumentException("Invalid CONSTANT_Utf8 index: " + constantPoolEntryIndex);
    }

    // The length of the Utf8 string is stored as a two‑byte unsigned short
    int len = ((classFileBuffer[startOffset] & 0xFF) << 8) | (classFileBuffer[startOffset + 1] & 0xFF);

    if (charBuffer.length < len) {
        throw new IllegalArgumentException("Provided char buffer too small (" + charBuffer.length + ") for Utf8 length (" + len + ")");
    }

    try {
        // Decode the bytes directly into a String using UTF-8
        // classFileBuffer[startOffset + 2] points to the first byte of the string
        return new String(classFileBuffer, startOffset + 2, len, java.nio.charset.StandardCharsets.UTF_8);
    } catch (RuntimeException e) {
        // Wrap any unexpected error
        throw new IllegalArgumentException("Failed to read CONSTANT_Utf8 entry", e);
    }
