    long result = 1L;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new NullPointerException("predicate");
    }
    if (start == null || stop == null) {
        throw new NullPointerException("start or stop");
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = start;
    while (true) {
        if (predicate.test(current)) {
            return circ;
        }
        if (current == stop) {
            return circ;
        }
        // Advance circulator in the requested direction
        circ.move(dir);
        current = circ.getNode();
        // Prevent an infinite loop in case of a malformed circulator
        if (current == start) {
            return circ;
        }
    }
}

