public Action inspect(AtmosphereResource r){
    try {
        if (r == null) {
            return Action.CONTINUE;
        }
        String trans = r.getTransport();
        if (trans == null) {
            return Action.CONTINUE;
        }
        // Automatically suspend based on transport type
        if ("WEBSOCKET".equalsIgnoreCase(trans)) {
            // Suspend indefinitely for WebSocket connections
            r.suspend(-1);
        } else if ("EVENTSOURCE".equalsIgnoreCase(trans) || "SSE".equalsIgnoreCase(trans)) {
            // Short suspension for Server Sent Events
            r.suspend(20000);
        } else {
            // Default timeout for other transports
            r.suspend(5000);
        }
    } catch (Exception e) {
        // Silently ignore any runtime issues
    }
    return Action.CONTINUE;
}

