protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if(tour == null || tour.isEmpty() || graph == null){
        return null;
    }
    try{
        // Map each vertex to its incident edges
        Map<V,Set<E>> adjacency = new HashMap<>();
        for(E e : tour){
            V source = graph.getEdgeSource(e);
            V target = graph.getEdgeTarget(e);
            adjacency.computeIfAbsent(source, k -> new HashSet<>()).add(e);
            adjacency.computeIfAbsent(target, k -> new HashSet<>()).add(e);
        }

        List<V> vertexList = new ArrayList<>();
        List<E> edgeList = new ArrayList<>();
        Set<E> remaining = new HashSet<>(tour);

        // Start from an arbitrary edge
        E startEdge = remaining.iterator().next();
        V startSource = graph.getEdgeSource(startEdge);
        V startTarget = graph.getEdgeTarget(startEdge);

        vertexList.add(startSource);
        edgeList.add(startEdge);
        vertexList.add(startTarget);
        remaining.remove(startEdge);

        V current = startTarget;
        while(!remaining.isEmpty()){
            boolean found = false;
            for(E e : new HashSet<>(remaining)){
                V s = graph.getEdgeSource(e);
                V t = graph.getEdgeTarget(e);
                if(s.equals(current)){
                    vertexList.add(t);
                    edgeList.add(e);
                    remaining.remove(e);
                    current = t;
                    found = true;
                    break;
                } else if(t.equals(current)){
                    // In case of undirected graph allow reverse direction
                    vertexList.add(s);
                    edgeList.add(e);
                    remaining.remove(e);
                    current = s;
                    found = true;
                    break;
                }
            }
            if(!found){
                // No connecting edge found, abort
                break;
            }
        }

        if(edgeList.isEmpty()){
            return null;
        }

        // Construct and return a GraphPath using GraphWalk implementation
        return new org.jgrapht.graph.GraphWalk<>(graph, vertexList, edgeList, true);
    }catch(Exception ex){
        // In case of any runtime issue return null
        return null;
    }
}

