int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    // Find or insert UTF8 entries for the name and descriptor
    int nameIdx = findUtf8(name);
    if (nameIdx == NOT_FOUND) {
        nameIdx = addUtf8(name);
    }
    int descIdx = findUtf8(descriptor);
    if (descIdx == NOT_FOUND) {
        descIdx = addUtf8(descriptor);
    }
    // Check if the NameAndType info already exists
    int existing = findNameAndType(nameIdx, descIdx);
    if (existing != NOT_FOUND) {
        return existing;
    }
    // Grow the constant pool if necessary
    if (maxPoolSize + 1 >= types.length) {
        growPool(); // assume all related arrays are resized here
    }
    int newIndex = ++maxPoolSize;
    types[newIndex] = NAME_TYPE;
    // Store the two indices in the constant pool data (big‑endian)
    int offset = newIndex * 4;
    byteCode[offset] = (byte)(nameIdx >> 8);
    byteCode[offset + 1] = (byte)(nameIdx & 0xff);
    byteCode[offset + 2] = (byte)(descIdx >> 8);
    byteCode[offset + 3] = (byte)(descIdx & 0xff);
    return newIndex;
}

