private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    if (bucketsByLabel == null || labels == null) {
        throw new IllegalArgumentException("bucketsByLabel and labels cannot be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds");
    }
    if (minLabel == 0) {
        // nothing to move, just ensure bucket 0 exists
        if (bucketsByLabel.get(0) == null) {
            bucketsByLabel.set(0, new HashSet<Integer>());
        }
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    Set<Integer> dest = bucketsByLabel.get(0);
    if (dest == null) {
        dest = new HashSet<Integer>();
        bucketsByLabel.set(0, dest);
    }
    for (Integer vertex : source) {
        dest.add(vertex);
        if (vertex >= 0 && vertex < labels.size()) {
            labels.set(vertex, 0);
        }
    }
    source.clear();
}

