    if (from < 0 || to >= len || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to);
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this) {
        return;
    }
    Object firstLock, secondLock;
    if (System.identityHashCode(this) < System.identityHashCode(list)) {
        firstLock = this;
        secondLock = list;
    } else {
        firstLock = list;
        secondLock = this;
    }
    synchronized (firstLock) {
        synchronized (secondLock) {
            ListNode<E> srcHead = list.head;
            if (srcHead == null) {
                return;
            }
            ListNode<E> srcTail = list.tail;
            int movedSize = list.size;
            list.head = null;
            list.tail = null;
            list.size = 0;
            if (this.head == null) {
                this.head = srcHead;
                this.tail = srcTail;
            } else {
                this.tail.next = srcHead;
                srcHead.prev = this.tail;
                this.tail = srcTail;
            }
            this.size += movedSize;
        }
    }
}

