private void addReverse(final File[] files) {
    if (files == null || files.length == 0) {
        return;
    }
    for (int i = files.length - 1; i >= 0; i--) {
        File file = files[i];
        if (file == null) {
            continue;
        }
        try {
            add(file);
        } catch (Exception e) {
            // If adding fails, wrap into a runtime exception to signal caller
            throw new RuntimeException("Failed to add file: " + file, e);
        }
    }
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }
    try {
        table.setRowSelectionInterval(row, row);
        Rectangle rect = table.getCellRect(row, 0, true);
        if (rect != null) {
            table.scrollRectToVisible(rect);
        }
        // Delay repaint to ensure proper painting of the newly selected row
        SwingUtilities.invokeLater(() -> table.repaint());
    } catch (Exception e) {
        // Handle potential runtime issues gracefully
        e.printStackTrace();
    }
}

