public static boolean arrayequals(byte[] a, byte[] b, int count) {
    // If count is zero or negative, trivially equal.
    if (count <= 0) {
        return true;
    }
    // Both arrays must be non-null and long enough.
    if (a == null || b == null) {
        return false;
    }
    if (a.length < count || b.length < count) {
        return false;
    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

