private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2) && graph.getEdge(v1, v2) == null) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        // For each key, the maximum lower bound is the index of the previous key
        // (or 0 for the first key if no lower bound exists).
        lowerBounds.add(i > 0 ? i - 1 : 0);
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int count = 0;
    int i = 0;
    // If descriptor starts with '(' treat it as a method descriptor and skip the argument part
    if (descriptor.charAt(0) == '(') {
        int endArgs = descriptor.indexOf(')');
        if (endArgs == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        i = endArgs + 1;  // Point at the return type (which we ignore)
    }
    // Parse the remaining type descriptors
    while (i < descriptor.length()) {
        char c = descriptor.charAt(i);
        switch (c) {
            case 'B':
            case 'C':
            case 'F':
            case 'I':
            case 'S':
            case 'Z':
                count += 1;
                i += 1;
                break;
            case 'J':
                count += 2;  // long occupies two words
                i += 1;
                break;
            case 'D':
                count += 2;  // double occupies two words
                i += 1;
                break;
            case 'L':  // object type
                int end = descriptor.indexOf(';', i);
                if (end == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
                }
                count += 1;
                i = end + 1;
                break;
            case '[':  // array type
                // Skip all consecutive '[' characters
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                // After '['s we must have a type (object or primitive)
                if (i >= descriptor.length()) {
                    throw new IllegalArgumentException("Invalid descriptor: incomplete array type");
                }
                char inner = descriptor.charAt(i);
                if (inner == 'L') {
                    int endObj = descriptor.indexOf(';', i);
                    if (endObj == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: missing ';' for array object type");
                    }
                    i = endObj + 1;
                } else {
                    // primitive type
                    i++;
                }
                count += 1;
                break;
            default:
                throw new IllegalArgumentException("Unknown descriptor type character: " + c);
        }
    }
    // Ensure we do not underflow the stack
    if (pos < count) {
        throw new IllegalStateException("Attempt to pop " + count + " elements from a smaller stack (current pos: " + pos + ")");
    }
    pos -= count;
}

