private List<Integer> computeUpperBounds(List<K> keys) {
    if (keys == null) {
        throw new IllegalArgumentException("keys cannot be null");
    }
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            // Represent missing key with the smallest possible bound
            bounds.add(Integer.MIN_VALUE);
            continue;
        }
        // If the key itself is an Integer, use it directly.
        if (key instanceof Integer) {
            bounds.add((Integer) key);
        } else if (key instanceof Number) {
            // For other numeric types, use their int value.
            bounds.add(((Number) key).intValue());
        } else {
            // For non-numeric keys, derive a bound from the hash code.
            // Subtracting from Integer.MAX_VALUE ensures the result
            // is in the upper range, providing a “minimum lower bound”
            // relative to typical integer sizes.
            bounds.add(Integer.MAX_VALUE - Math.abs(key.hashCode()));
        }
    }
    return bounds;
}

