public static String applyRelativePath(String path,String relativePath){
    if (path == null || relativePath == null){
        return null;
    }
    boolean absolute = path.startsWith("/");
    // Split path and push to stack
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    String[] pathParts = path.split("/", -1);
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        stack.add(part);
    }
    // Apply relative parts
    String[] relParts = relativePath.split("/", -1);
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.add(part);
        }
    }
    // Build final path
    StringBuilder sb = new StringBuilder();
    if (absolute) {
        sb.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) {
            sb.append("/");
        }
    }
    // If result is empty but original was absolute, return root "/"
    if (sb.length() == 0 && absolute) {
        return "/";
    }
    return sb.toString();
}

