Edge edgeToNext(){
    // Assume this class keeps track of the last node returned and the node to be returned next
    // using the fields _previousNode and _nextNode.
    // The edges of the graph are stored in the field _edges.
    if (this._previousNode == null || this._nextNode == null) {
        return null;
    }
    if (this._edges == null) {
        return null;
    }
    for (Edge e : this._edges) {
        // If either node is virtual, use the real counterpart when comparing.
        // We assume that the Node class has methods isVirtual() and getRealNode().
        Node from = e.getFrom();
        Node to = e.getTo();
        if (this._previousNode.isVirtual()) {
            from = this._previousNode.getRealNode();
        }
        if (this._nextNode.isVirtual()) {
            to = this._nextNode.getRealNode();
        }
        if (from == this._previousNode || from == this._previousNode.getRealNode()) {
            if (to == this._nextNode || to == this._nextNode.getRealNode()) {
                return e;
            }
        }
    }
    return null;
}

