private void checkIfPackedField() throws IOException {
    // Determine if the current field should be treated as a packed repeated field.
    if ((tag & 0x7) == WireFormat.WIRETYPE_LENGTH_DELIMITED && field != null && field.isPacked()) {
        // Read the length of the packed data and set the limit accordingly.
        int packedLength = readRawVarint32();
        limit = getPosition() + packedLength;
        // Update internal state to indicate packed field reading.
        readingPackedField = true;
    } else {
        readingPackedField = false;
    }
}

